package com.shivhub.backend.entity;
import jakarta.persistence.*; import lombok.Data;
@Entity @Table(name="marketplace_attribute_definitions", uniqueConstraints=@UniqueConstraint(columnNames={"subcategory_id","attribute_key"})) @Data
public class MarketplaceAttributeDefinition { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subcategory_id",nullable=false) private MarketplaceSubcategory subcategory; @Column(name="attribute_key",nullable=false,length=80) private String attributeKey; @Column(name="display_name",nullable=false,length=120) private String displayName; @Column(name="input_type",nullable=false,length=30) private String inputType="TEXT"; @Column(name="options_json",columnDefinition="TEXT") private String optionsJson; @Column(name="required_field",nullable=false) private boolean requiredField; @Column(name="display_order",nullable=false) private int displayOrder; private boolean active=true; }
